var a=`1203-pollo-chuco`;var o=`world-1203`;var i=`HN`;var t=`central-america-caribbean`;var r=4;var s=117;var l={en:`Pollo Chuco`,ua:`Польо чуко`};var u={en:`Pollo Chuco is a dish from Honduras featuring chicken leg quarter, orange juice, garlic, plantain. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Польо чуко, страва кухні країни Гондурас з такими основними складниками: курячий окорочок, апельсиновий сік, часник, плантан. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 75 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 75 хвилин.`,t:[`marinating`],m:75,i:[[`chicken-leg-quarter`,950,`g`],[`orange-juice`,140,`ml`],[`garlic`,5,`clove`],[`ground-cumin`,5,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 20 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 20 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:20,i:[[`canola-oil`,850,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`plantain`,600,`g`],[`canola-oil`,130,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`white-cabbage`,260,`g`],[`tomato`,220,`g`],[`sour-cream`,130,`g`],[`hot-sauce`,50,`ml`]]}];var c={slug:a,id:o,country:`HN`,region:t,servings:4,minutes:117,title:l,text:u,steps:g};export{i as country,c as default,o as id,s as minutes,t as region,r as servings,a as slug,g as steps,u as text,l as title};